const sqlite3 = require('sqlite3').verbose();
const crypto = require('crypto');
const path = require('path');
const fs = require('fs');

const DB_PATH = path.join(__dirname, '..', 'brickfall.db');

function getDb() {
  return new sqlite3.Database(DB_PATH);
}

function initializeDatabase() {
  return new Promise((resolve, reject) => {
    const db = getDb();

    db.serialize(() => {
      // Users table
      db.run(`
        CREATE TABLE IF NOT EXISTS users (
          id INTEGER PRIMARY KEY,
          email TEXT UNIQUE NOT NULL,
          name TEXT NOT NULL,
          initials TEXT NOT NULL,
          password_hash TEXT NOT NULL,
          password_salt TEXT NOT NULL,
          highest_level INTEGER DEFAULT 1,
          best_score INTEGER DEFAULT 0,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
      `);

      // Tokens table
      db.run(`
        CREATE TABLE IF NOT EXISTS tokens (
          id INTEGER PRIMARY KEY,
          user_id INTEGER NOT NULL,
          token TEXT UNIQUE NOT NULL,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          FOREIGN KEY (user_id) REFERENCES users(id)
        )
      `);

      // Levels table
      db.run(`
        CREATE TABLE IF NOT EXISTS levels (
          level INTEGER PRIMARY KEY,
          name TEXT NOT NULL,
          base_speed INTEGER NOT NULL,
          speed_cap INTEGER NOT NULL,
          accent TEXT NOT NULL
        )
      `);

      // Bricks table
      db.run(`
        CREATE TABLE IF NOT EXISTS bricks (
          id INTEGER PRIMARY KEY,
          level INTEGER NOT NULL,
          row INTEGER NOT NULL,
          column INTEGER NOT NULL,
          type TEXT NOT NULL,
          drop TEXT,
          FOREIGN KEY (level) REFERENCES levels(level)
        )
      `);

      // Leaderboard table
      db.run(`
        CREATE TABLE IF NOT EXISTS leaderboard (
          id INTEGER PRIMARY KEY,
          user_id INTEGER,
          initials TEXT NOT NULL,
          score INTEGER NOT NULL,
          level INTEGER NOT NULL,
          achieved_at DATETIME NOT NULL,
          email TEXT,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
      `);

      // Run snapshots table
      db.run(`
        CREATE TABLE IF NOT EXISTS run_snapshots (
          id INTEGER PRIMARY KEY,
          user_id INTEGER NOT NULL,
          run_id TEXT UNIQUE NOT NULL,
          revision INTEGER NOT NULL,
          level INTEGER NOT NULL,
          score INTEGER NOT NULL,
          lives INTEGER NOT NULL,
          combo INTEGER NOT NULL,
          next_extra_life INTEGER NOT NULL,
          power TEXT,
          power_seconds REAL,
          paddle_width INTEGER NOT NULL,
          balls TEXT NOT NULL,
          drops TEXT NOT NULL,
          bricks TEXT NOT NULL,
          simulation_time REAL NOT NULL,
          state TEXT NOT NULL,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          FOREIGN KEY (user_id) REFERENCES users(id)
        )
      `);

      // Run history table (terminal runs)
      db.run(`
        CREATE TABLE IF NOT EXISTS run_history (
          id INTEGER PRIMARY KEY,
          user_id INTEGER NOT NULL,
          run_id TEXT NOT NULL,
          outcome TEXT NOT NULL,
          level INTEGER NOT NULL,
          score INTEGER NOT NULL,
          snapshot TEXT NOT NULL,
          finished_at DATETIME NOT NULL,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          FOREIGN KEY (user_id) REFERENCES users(id)
        )
      `);

      // Constants table
      db.run(`
        CREATE TABLE IF NOT EXISTS constants (
          key TEXT PRIMARY KEY,
          value TEXT NOT NULL
        )
      `);

      // Request receipts table (for idempotency)
      db.run(`
        CREATE TABLE IF NOT EXISTS request_receipts (
          id INTEGER PRIMARY KEY,
          user_id INTEGER NOT NULL,
          operation_id TEXT NOT NULL,
          revision INTEGER NOT NULL,
          status INTEGER NOT NULL,
          response TEXT NOT NULL,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          UNIQUE(user_id, operation_id),
          FOREIGN KEY (user_id) REFERENCES users(id)
        )
      `);

      // Mechanics lab drills table
      db.run(`
        CREATE TABLE IF NOT EXISTS drills (
          id TEXT PRIMARY KEY,
          name TEXT NOT NULL,
          initial TEXT NOT NULL,
          after_advance TEXT NOT NULL,
          after_second_advance TEXT
        )
      `);

      // Checkpoint snapshots table
      db.run(`
        CREATE TABLE IF NOT EXISTS checkpoints (
          id INTEGER PRIMARY KEY,
          user_id INTEGER NOT NULL,
          revision INTEGER NOT NULL,
          level INTEGER NOT NULL,
          score INTEGER NOT NULL,
          lives INTEGER NOT NULL,
          combo INTEGER NOT NULL,
          next_extra_life INTEGER NOT NULL,
          power TEXT,
          power_seconds REAL,
          paddle_width INTEGER NOT NULL,
          balls TEXT NOT NULL,
          drops TEXT NOT NULL,
          bricks TEXT NOT NULL,
          simulation_time REAL NOT NULL,
          next_outcome TEXT NOT NULL,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          FOREIGN KEY (user_id) REFERENCES users(id)
        )
      `, (err) => {
        if (err) {
          reject(err);
        } else {
          resolve();
        }
      });
    });

    db.close();
  });
}

function seedDatabase() {
  return new Promise((resolve, reject) => {
    const db = getDb();

    db.serialize(() => {
      // Check if already seeded
      db.get("SELECT COUNT(*) as count FROM users", (err, row) => {
        if (err) {
          reject(err);
          return;
        }

        if (row.count > 0) {
          // Already seeded
          db.close();
          resolve();
          return;
        }

        // Load seed data
        const seedPath = path.join(__dirname, '..', '..', 'assets', 'artifacts', 'brickfall_seed.xlsx');
        const scenariosPath = path.join(__dirname, '..', '..', 'assets', 'artifacts', 'brickfall_scenarios.json');

        try {
          const openpyxl = require('openpyxl');
          const XLSX = require('xlsx');

          // Read Excel file
          const workbook = XLSX.readFile(seedPath);

          // Seed users
          const usersSheet = XLSX.utils.sheet_to_json(workbook.Sheets['Users']);
          usersSheet.forEach(user => {
            const salt = crypto.randomBytes(16).toString('hex');
            const hash = crypto.pbkdf2Sync(user.password, salt, 100000, 64, 'sha256').toString('hex');
            db.run(
              `INSERT INTO users (email, name, initials, password_hash, password_salt, highest_level, best_score)
               VALUES (?, ?, ?, ?, ?, ?, ?)`,
              [user.email, user.name, user.initials, hash, salt, user.highest_level, user.best_score]
            );
          });

          // Seed levels
          const levelsSheet = XLSX.utils.sheet_to_json(workbook.Sheets['Levels']);
          levelsSheet.forEach(level => {
            db.run(
              `INSERT INTO levels (level, name, base_speed, speed_cap, accent)
               VALUES (?, ?, ?, ?, ?)`,
              [level.level, level.name, level.base_speed, level.speed_cap, level.accent]
            );
          });

          // Seed bricks
          const bricksSheet = XLSX.utils.sheet_to_json(workbook.Sheets['Bricks']);
          bricksSheet.forEach(brick => {
            db.run(
              `INSERT INTO bricks (level, row, column, type, drop)
               VALUES (?, ?, ?, ?, ?)`,
              [brick.level, brick.row, brick.column, brick.type, brick.drop || null]
            );
          });

          // Seed leaderboard
          const leaderboardSheet = XLSX.utils.sheet_to_json(workbook.Sheets['Leaderboard']);
          leaderboardSheet.forEach(entry => {
            db.run(
              `INSERT INTO leaderboard (initials, score, level, achieved_at, email)
               VALUES (?, ?, ?, ?, ?)`,
              [entry.initials, entry.score, entry.level, entry.achieved_at, entry.email || null]
            );
          });

          // Seed constants
          const constantsSheet = XLSX.utils.sheet_to_json(workbook.Sheets['Constants']);
          constantsSheet.forEach(constant => {
            db.run(
              `INSERT INTO constants (key, value) VALUES (?, ?)`,
              [constant.key, String(constant.value)]
            );
          });

          // Load scenarios
          const scenarios = JSON.parse(fs.readFileSync(scenariosPath, 'utf8'));

          // Seed guest leaderboard entries
          scenarios.guest_leaderboard.forEach(entry => {
            db.run(
              `INSERT INTO leaderboard (initials, score, level, achieved_at, email)
               VALUES (?, ?, ?, ?, ?)`,
              [entry.initials, entry.score, entry.level, entry.achieved_at, null]
            );
          });

          // Seed drills
          scenarios.drills.forEach(drill => {
            db.run(
              `INSERT INTO drills (id, name, initial, after_advance, after_second_advance)
               VALUES (?, ?, ?, ?, ?)`,
              [drill.id, drill.name, drill.initial, drill.after_advance, drill.after_second_advance || null]
            );
          });

          // Seed checkpoints for Mira and Dev
          db.all("SELECT id, email FROM users WHERE email IN ('mira@brickfall.test', 'dev@brickfall.test')", (err, users) => {
            if (err) {
              reject(err);
              return;
            }

            users.forEach(user => {
              const checkpoint = scenarios.checkpoints[user.email.split('@')[0]];
              if (checkpoint) {
                db.run(
                  `INSERT INTO checkpoints (user_id, revision, level, score, lives, combo, next_extra_life, power, power_seconds, paddle_width, balls, drops, bricks, simulation_time, next_outcome)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
                  [user.id, checkpoint.revision, checkpoint.level, checkpoint.score, checkpoint.lives, checkpoint.combo, checkpoint.next_extra_life, checkpoint.power || null, checkpoint.power_seconds || null, checkpoint.paddle_width || 118, checkpoint.balls || '', checkpoint.drop || '', '', 0, checkpoint.next_outcome || '']
                );
              }
            });

            // Seed Polly's run history
            db.get("SELECT id FROM users WHERE email = 'polly@brickfall.test'", (err, pollyUser) => {
              if (err) {
                reject(err);
                return;
              }

              if (pollyUser) {
                scenarios.personal_run_fixtures.forEach(fixture => {
                  db.run(
                    `INSERT INTO run_history (user_id, run_id, outcome, level, score, snapshot, finished_at)
                     VALUES (?, ?, ?, ?, ?, ?, ?)`,
                    [pollyUser.id, fixture.run_id, fixture.outcome, fixture.level, fixture.score, '{}', fixture.finished_at]
                  );
                });
              }

              db.close();
              resolve();
            });
          });
        } catch (err) {
          db.close();
          reject(err);
        }
      });
    });
  });
}

module.exports = {
  getDb,
  initializeDatabase,
  seedDatabase
};

{
  "name": "brickfall",
  "version": "1.0.0",
  "description": "A brick-breaker arcade game with persistent player profiles and mechanics lab",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "dev": "node server.js"
  },
  "dependencies": {
    "express": "^4.18.2",
    "sqlite3": "^5.1.6",
    "crypto": "^1.0.1",
    "xlsx": "^0.18.5"
  }
}

const crypto = require('crypto');
const { getDb } = require('./db');

function hashPassword(password, salt) {
  return crypto.pbkdf2Sync(password, salt, 100000, 64, 'sha256').toString('hex');
}

function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

function signIn(email, password) {
  return new Promise((resolve, reject) => {
    const db = getDb();

    db.get(
      "SELECT id, email, name, initials, password_hash, password_salt FROM users WHERE email = ?",
      [email],
      (err, user) => {
        if (err) {
          db.close();
          reject(err);
          return;
        }

        if (!user) {
          db.close();
          resolve(null);
          return;
        }

        const hash = hashPassword(password, user.password_salt);
        if (hash !== user.password_hash) {
          db.close();
          resolve(null);
          return;
        }

        // Generate token
        const token = generateToken();

        // Revoke existing tokens for this user
        db.run("DELETE FROM tokens WHERE user_id = ?", [user.id], (err) => {
          if (err) {
            db.close();
            reject(err);
            return;
          }

          // Store new token
          db.run(
            "INSERT INTO tokens (user_id, token) VALUES (?, ?)",
            [user.id, token],
            (err) => {
              db.close();
              if (err) {
                reject(err);
              } else {
                resolve({
                  token,
                  user: {
                    id: user.id,
                    email: user.email,
                    name: user.name,
                    initials: user.initials
                  }
                });
              }
            }
          );
        });
      }
    );
  });
}

function verifyToken(token) {
  return new Promise((resolve, reject) => {
    const db = getDb();

    db.get(
      `SELECT u.id, u.email, u.name, u.initials, u.highest_level, u.best_score
       FROM tokens t
       JOIN users u ON t.user_id = u.id
       WHERE t.token = ?`,
      [token],
      (err, row) => {
        db.close();
        if (err) {
          reject(err);
        } else {
          resolve(row || null);
        }
      }
    );
  });
}

function signOut(token) {
  return new Promise((resolve, reject) => {
    const db = getDb();

    db.run(
      "DELETE FROM tokens WHERE token = ?",
      [token],
      (err) => {
        db.close();
        if (err) {
          reject(err);
        } else {
          resolve();
        }
      }
    );
  });
}

function getRunRevision(userId) {
  return new Promise((resolve, reject) => {
    const db = getDb();

    db.get(
      "SELECT MAX(revision) as max_revision FROM run_snapshots WHERE user_id = ?",
      [userId],
      (err, row) => {
        db.close();
        if (err) {
          reject(err);
        } else {
          resolve((row?.max_revision || 0) + 1);
        }
      }
    );
  });
}

module.exports = {
  hashPassword,
  generateToken,
  signIn,
  verifyToken,
  signOut,
  getRunRevision
};

// Physics engine with fixed timestep and collision detection

const PHYSICS_STEP = 1 / 120; // 1/120 second per step
const MIN_VELOCITY = 50;
const EPSILON = 0.001;

class Vector2 {
  constructor(x = 0, y = 0) {
    this.x = x;
    this.y = y;
  }

  add(v) {
    return new Vector2(this.x + v.x, this.y + v.y);
  }

  subtract(v) {
    return new Vector2(this.x - v.x, this.y - v.y);
  }

  multiply(scalar) {
    return new Vector2(this.x * scalar, this.y * scalar);
  }

  dot(v) {
    return this.x * v.x + this.y * v.y;
  }

  length() {
    return Math.sqrt(this.x * this.x + this.y * this.y);
  }

  normalize() {
    const len = this.length();
    if (len === 0) return new Vector2(0, 0);
    return new Vector2(this.x / len, this.y / len);
  }

  clone() {
    return new Vector2(this.x, this.y);
  }
}

class Ball {
  constructor(x, y, vx, vy, radius = 9, id = 'primary') {
    this.x = x;
    this.y = y;
    this.vx = vx;
    this.vy = vy;
    this.radius = radius;
    this.id = id;
    this.stuck = false;
    this.stuckToPaddle = false;
  }

  clone() {
    const b = new Ball(this.x, this.y, this.vx, this.vy, this.radius, this.id);
    b.stuck = this.stuck;
    b.stuckToPaddle = this.stuckToPaddle;
    return b;
  }
}

class Brick {
  constructor(x, y, width, height, type = 'normal', drop = null) {
    this.x = x;
    this.y = y;
    this.width = width;
    this.height = height;
    this.type = type; // 'normal', 'strong', 'solid'
    this.drop = drop; // 'wide', 'slow', 'multiball', 'sticky', null
    this.health = type === 'strong' ? 2 : (type === 'normal' ? 1 : 0);
    this.damaged = false; // For strong bricks
  }

  isBreakable() {
    return this.type !== 'solid';
  }

  clone() {
    const b = new Brick(this.x, this.y, this.width, this.height, this.type, this.drop);
    b.health = this.health;
    b.damaged = this.damaged;
    return b;
  }
}

class Paddle {
  constructor(x, y, width, height) {
    this.x = x;
    this.y = y;
    this.width = width;
    this.height = height;
    this.baseWidth = width;
    this.vx = 0;
  }

  clone() {
    const p = new Paddle(this.x, this.y, this.width, this.height);
    p.baseWidth = this.baseWidth;
    p.vx = this.vx;
    return p;
  }
}

class Drop {
  constructor(x, y, type) {
    this.x = x;
    this.y = y;
    this.type = type; // 'wide', 'slow', 'multiball', 'sticky'
    this.vx = 0;
    this.vy = 150; // Falling speed
    this.radius = 8;
  }

  clone() {
    const d = new Drop(this.x, this.y, this.type);
    d.vx = this.vx;
    d.vy = this.vy;
    return d;
  }
}

// Swept circle collision detection
function sweepCircleRect(ballPos, ballVel, ballRadius, rectX, rectY, rectW, rectH, dt) {
  const nextPos = ballPos.add(ballVel.multiply(dt));

  // Find closest point on rect to ball's swept path
  const closestX = Math.max(rectX, Math.min(ballPos.x, rectX + rectW));
  const closestY = Math.max(rectY, Math.min(ballPos.y, rectY + rectH));

  const dx = ballPos.x - closestX;
  const dy = ballPos.y - closestY;
  const distSq = dx * dx + dy * dy;

  if (distSq > ballRadius * ballRadius) {
    return null; // No collision
  }

  // Find collision point more precisely
  const dist = Math.sqrt(distSq);
  if (dist < EPSILON) {
    // Ball center is inside rect, find exit point
    const centerX = rectX + rectW / 2;
    const centerY = rectY + rectH / 2;
    const dx2 = ballPos.x - centerX;
    const dy2 = ballPos.y - centerY;
    const dist2 = Math.sqrt(dx2 * dx2 + dy2 * dy2);

    if (dist2 < EPSILON) {
      // Ball at center, default to top collision
      return {
        point: new Vector2(ballPos.x, rectY),
        normal: new Vector2(0, -1),
        face: 'top'
      };
    }

    const norm = new Vector2(dx2 / dist2, dy2 / dist2);
    return {
      point: new Vector2(ballPos.x - norm.x * ballRadius, ballPos.y - norm.y * ballRadius),
      normal: norm,
      face: determineFace(ballPos, rectX, rectY, rectW, rectH)
    };
  }

  const normal = new Vector2(dx / dist, dy / dist);
  return {
    point: new Vector2(closestX + normal.x * ballRadius, closestY + normal.y * ballRadius),
    normal: normal,
    face: determineFace(new Vector2(closestX, closestY), rectX, rectY, rectW, rectH)
  };
}

function determineFace(point, rectX, rectY, rectW, rectH) {
  const centerX = rectX + rectW / 2;
  const centerY = rectY + rectH / 2;

  const dx = Math.abs(point.x - centerX);
  const dy = Math.abs(point.y - centerY);

  const halfW = rectW / 2;
  const halfH = rectH / 2;

  // Determine which face was hit
  if (dx / halfW > dy / halfH) {
    return point.x < centerX ? 'left' : 'right';
  } else {
    return point.y < centerY ? 'top' : 'bottom';
  }
}

function reflectVelocity(velocity, normal, face) {
  // Reflect velocity across normal
  const dot = velocity.dot(normal);
  const reflected = velocity.subtract(normal.multiply(2 * dot));

  // Ensure minimum velocity components
  let vx = reflected.x;
  let vy = reflected.y;

  if (Math.abs(vx) < MIN_VELOCITY && Math.abs(vy) > 0) {
    vx = Math.sign(vx) * MIN_VELOCITY;
  }
  if (Math.abs(vy) < MIN_VELOCITY && Math.abs(vx) > 0) {
    vy = Math.sign(vy) * MIN_VELOCITY;
  }

  return new Vector2(vx, vy);
}

function clampSpeed(velocity, speedCap) {
  const speed = velocity.length();
  if (speed > speedCap) {
    return velocity.normalize().multiply(speedCap);
  }
  return velocity;
}

module.exports = {
  Vector2,
  Ball,
  Brick,
  Paddle,
  Drop,
  PHYSICS_STEP,
  MIN_VELOCITY,
  sweepCircleRect,
  reflectVelocity,
  clampSpeed,
  determineFace
};

const { Ball, Brick, Paddle, Drop, Vector2, PHYSICS_STEP, sweepCircleRect, reflectVelocity, clampSpeed } = require('./physics');
const { getDb } = require('./db');

const CANVAS_WIDTH = 900;
const CANVAS_HEIGHT = 600;
const BRICK_WIDTH = 80;
const BRICK_HEIGHT = 20;
const BRICK_PADDING = 5;
const PADDLE_HEIGHT = 18;
const BALL_RADIUS = 9;

const STATES = {
  MENU: 'menu',
  READY: 'ready',
  PLAYING: 'playing',
  PAUSED: 'paused',
  LIFE_LOST: 'life-lost',
  LEVEL_COMPLETE: 'level-complete',
  GAME_OVER: 'game-over',
  COMPLETED: 'completed'
};

class GameState {
  constructor(level, baseSpeed, speedCap, bricks, constants) {
    this.level = level;
    this.baseSpeed = baseSpeed;
    this.speedCap = speedCap;
    this.bricks = bricks.map(b => new Brick(b.x, b.y, b.width, b.height, b.type, b.drop));

    this.score = 0;
    this.lives = constants.initial_lives;
    this.combo = 1;
    this.nextExtraLife = constants.extra_life_step;

    this.paddle = new Paddle(CANVAS_WIDTH / 2 - 59, CANVAS_HEIGHT - 40, 118, PADDLE_HEIGHT);
    this.balls = [new Ball(CANVAS_WIDTH / 2, CANVAS_HEIGHT - 60, 0, -baseSpeed, BALL_RADIUS, 'primary')];
    this.balls[0].stuck = true;

    this.drops = [];
    this.power = null;
    this.powerSeconds = 0;

    this.state = STATES.READY;
    this.simulationTime = 0;
    this.accumulator = 0;

    this.events = [];
    this.lastBrickHitId = null;
    this.assistPaddleActive = false;

    this.constants = constants;
  }

  static fromSnapshot(snapshot, constants) {
    const gs = new GameState(snapshot.level, constants.base_speed, constants.speed_cap, [], constants);

    gs.score = snapshot.score;
    gs.lives = snapshot.lives;
    gs.combo = snapshot.combo;
    gs.nextExtraLife = snapshot.next_extra_life;
    gs.paddle = new Paddle(snapshot.paddle_x, snapshot.paddle_y, snapshot.paddle_width, PADDLE_HEIGHT);
    gs.paddle.baseWidth = 118;

    gs.balls = snapshot.balls.map(b => {
      const ball = new Ball(b.x, b.y, b.vx, b.vy, BALL_RADIUS, b.id);
      ball.stuck = b.stuck;
      ball.stuckToPaddle = b.stuck_to_paddle;
      return ball;
    });

    gs.drops = snapshot.drops.map(d => new Drop(d.x, d.y, d.type));
    gs.power = snapshot.power;
    gs.powerSeconds = snapshot.power_seconds;

    gs.bricks = snapshot.bricks.map(b => {
      const brick = new Brick(b.x, b.y, b.width, b.height, b.type, b.drop);
      brick.health = b.health;
      brick.damaged = b.damaged;
      return brick;
    });

    gs.state = snapshot.state;
    gs.simulationTime = snapshot.simulation_time;
    gs.accumulator = 0;

    return gs;
  }

  toSnapshot() {
    return {
      level: this.level,
      score: this.score,
      lives: this.lives,
      combo: this.combo,
      next_extra_life: this.nextExtraLife,
      paddle_x: this.paddle.x,
      paddle_y: this.paddle.y,
      paddle_width: this.paddle.width,
      balls: this.balls.map(b => ({
        id: b.id,
        x: b.x,
        y: b.y,
        vx: b.vx,
        vy: b.vy,
        stuck: b.stuck,
        stuck_to_paddle: b.stuckToPaddle
      })),
      drops: this.drops.map(d => ({
        x: d.x,
        y: d.y,
        type: d.type
      })),
      power: this.power,
      power_seconds: this.powerSeconds,
      bricks: this.bricks.map(b => ({
        x: b.x,
        y: b.y,
        width: b.width,
        height: b.height,
        type: b.type,
        drop: b.drop,
        health: b.health,
        damaged: b.damaged
      })),
      state: this.state,
      simulation_time: this.simulationTime
    };
  }

  update(dt) {
    if (this.state === STATES.PAUSED || this.state === STATES.READY) {
      return;
    }

    this.accumulator += dt;
    this.events = [];

    while (this.accumulator >= PHYSICS_STEP) {
      this.simulationStep();
      this.accumulator -= PHYSICS_STEP;
      this.simulationTime += PHYSICS_STEP;
    }
  }

  simulationStep() {
    // Update power-up timer
    if (this.power) {
      this.powerSeconds -= PHYSICS_STEP;
      if (this.powerSeconds <= 0) {
        this.endPowerUp();
      }
    }

    // Update drops
    this.updateDrops();

    // Update balls
    this.updateBalls();

    // Check for level completion
    const breakableBricks = this.bricks.filter(b => b.isBreakable() && b.health > 0);
    if (breakableBricks.length === 0) {
      this.completeLevel();
    }

    // Check for game over
    if (this.balls.length === 0 && this.lives === 0) {
      this.gameOver();
    }
  }

  updateBalls() {
    const ballsCopy = [...this.balls];

    for (let i = 0; i < ballsCopy.length; i++) {
      const ball = ballsCopy[i];

      if (ball.stuck) {
        // Stuck ball follows paddle
        ball.x = this.paddle.x + this.paddle.width / 2;
        ball.y = this.paddle.y - ball.radius;
        continue;
      }

      // Move ball
      const newX = ball.x + ball.vx * PHYSICS_STEP;
      const newY = ball.y + ball.vy * PHYSICS_STEP;

      // Check collisions with bricks
      let hitBrick = null;
      for (let j = 0; j < this.bricks.length; j++) {
        const brick = this.bricks[j];
        const collision = sweepCircleRect(
          new Vector2(ball.x, ball.y),
          new Vector2(ball.vx, ball.vy),
          ball.radius,
          brick.x,
          brick.y,
          brick.width,
          brick.height,
          PHYSICS_STEP
        );

        if (collision) {
          hitBrick = { brick, collision, index: j };
          break;
        }
      }

      if (hitBrick) {
        const { brick, collision } = hitBrick;
        ball.x = collision.point.x;
        ball.y = collision.point.y;
        ball.vx = reflectVelocity(new Vector2(ball.vx, ball.vy), collision.normal, collision.face).x;
        ball.vy = reflectVelocity(new Vector2(ball.vx, ball.vy), collision.normal, collision.face).y;
        ball.vx = clampSpeed(new Vector2(ball.vx, ball.vy), this.speedCap).x;
        ball.vy = clampSpeed(new Vector2(ball.vx, ball.vy), this.speedCap).y;

        // Damage brick
        if (brick.isBreakable() && hitBrick.index !== this.lastBrickHitId) {
          this.lastBrickHitId = hitBrick.index;

          if (brick.type === 'normal') {
            this.score += 100 * this.combo;
            this.events.push({ type: 'brick-hit', points: 100 * this.combo, combo: this.combo });
            brick.health = 0;

            // Check for drop
            if (brick.drop) {
              this.drops.push(new Drop(brick.x + brick.width / 2, brick.y + brick.height, brick.drop));
            }
          } else if (brick.type === 'strong') {
            if (!brick.damaged) {
              this.score += 75 * this.combo;
              this.events.push({ type: 'brick-hit', points: 75 * this.combo, combo: this.combo });
              brick.damaged = true;
            } else {
              this.score += 250 * this.combo;
              this.events.push({ type: 'brick-hit', points: 250 * this.combo, combo: this.combo });
              brick.health = 0;

              // Check for drop
              if (brick.drop) {
                this.drops.push(new Drop(brick.x + brick.width / 2, brick.y + brick.height, brick.drop));
              }
            }
          }

          this.combo = Math.min(this.combo + 1, 5);

          // Check for extra life
          if (this.score >= this.nextExtraLife) {
            this.lives++;
            this.events.push({ type: 'extra-life', lives: this.lives });
            this.nextExtraLife += this.constants.extra_life_step;
          }
        }
      } else {
        // Check paddle collision
        const paddleCollision = sweepCircleRect(
          new Vector2(ball.x, ball.y),
          new Vector2(ball.vx, ball.vy),
          ball.radius,
          this.paddle.x,
          this.paddle.y,
          this.paddle.width,
          this.paddle.height,
          PHYSICS_STEP
        );

        if (paddleCollision) {
          ball.x = paddleCollision.point.x;
          ball.y = paddleCollision.point.y;

          // Steering based on paddle position
          const paddleCenter = this.paddle.x + this.paddle.width / 2;
          const hitOffset = (ball.x - paddleCenter) / (this.paddle.width / 2);
          const steerAngle = hitOffset * Math.PI / 6; // ±30 degrees

          const speed = Math.sqrt(ball.vx * ball.vx + ball.vy * ball.vy);
          ball.vx = Math.sin(steerAngle) * speed + this.paddle.vx * 0.3;
          ball.vy = -Math.cos(steerAngle) * speed;

          ball.vx = clampSpeed(new Vector2(ball.vx, ball.vy), this.speedCap).x;
          ball.vy = clampSpeed(new Vector2(ball.vx, ball.vy), this.speedCap).y;

          this.combo = 1;
          this.events.push({ type: 'paddle-hit' });

          if (ball.stuck) {
            ball.stuck = false;
            ball.stuckToPaddle = false;
          }
        } else {
          ball.x = newX;
          ball.y = newY;
        }
      }

      // Check if ball is out of bounds
      if (ball.y > CANVAS_HEIGHT) {
        this.balls = this.balls.filter(b => b.id !== ball.id);

        if (this.balls.length === 0) {
          this.loseLife();
        }
      }
    }
  }

  updateDrops() {
    for (let i = this.drops.length - 1; i >= 0; i--) {
      const drop = this.drops[i];
      drop.y += drop.vy * PHYSICS_STEP;

      // Check paddle collision
      if (drop.y + drop.radius > this.paddle.y &&
          drop.y - drop.radius < this.paddle.y + this.paddle.height &&
          drop.x + drop.radius > this.paddle.x &&
          drop.x - drop.radius < this.paddle.x + this.paddle.width) {

        this.collectPowerUp(drop.type);
        this.drops.splice(i, 1);
        this.events.push({ type: 'power-collected', power: drop.type });
      } else if (drop.y > CANVAS_HEIGHT) {
        this.drops.splice(i, 1);
      }
    }
  }

  collectPowerUp(type) {
    if (this.power === type) {
      // Reset timer
      this.powerSeconds = this.constants.powerup_duration_seconds;
    } else {
      // Replace power
      if (this.power) {
        this.endPowerUp();
      }

      this.power = type;
      this.powerSeconds = this.constants.powerup_duration_seconds;

      if (type === 'wide') {
        this.paddle.width = this.paddle.baseWidth * 1.5;
      } else if (type === 'slow') {
        const speed = Math.sqrt(this.balls[0].vx ** 2 + this.balls[0].vy ** 2);
        const newSpeed = speed * 0.7;
        const factor = newSpeed / speed;
        this.balls.forEach(b => {
          b.vx *= factor;
          b.vy *= factor;
        });
      } else if (type === 'multiball') {
        if (this.balls.length === 1) {
          const primary = this.balls[0];
          const secondary = new Ball(primary.x, primary.y, primary.vx, primary.vy, BALL_RADIUS, 'secondary');
          this.balls.push(secondary);
        }
      } else if (type === 'sticky') {
        if (this.balls.length > 0) {
          this.balls[0].stuck = true;
          this.balls[0].stuckToPaddle = true;
        }
      }
    }
  }

  endPowerUp() {
    if (this.power === 'wide') {
      this.paddle.width = this.paddle.baseWidth;
    } else if (this.power === 'slow') {
      // Restore speed to level cap
      this.balls.forEach(b => {
        const speed = Math.sqrt(b.vx ** 2 + b.vy ** 2);
        if (speed > 0) {
          const factor = Math.min(this.speedCap, speed) / speed;
          b.vx *= factor;
          b.vy *= factor;
        }
      });
    } else if (this.power === 'multiball') {
      // Keep only primary ball
      this.balls = this.balls.filter(b => b.id === 'primary');
    } else if (this.power === 'sticky') {
      // Release stuck ball
      if (this.balls.length > 0 && this.balls[0].stuck) {
        this.balls[0].stuck = false;
        this.balls[0].stuckToPaddle = false;
      }
    }

    this.power = null;
    this.powerSeconds = 0;
  }

  loseLife() {
    this.lives--;
    this.drops = [];
    this.endPowerUp();

    if (this.lives > 0) {
      this.state = STATES.LIFE_LOST;
      this.events.push({ type: 'life-lost', lives: this.lives });
    } else {
      this.gameOver();
    }
  }

  completeLevel() {
    this.score += 1000 * this.level;
    this.state = STATES.LEVEL_COMPLETE;
    this.events.push({ type: 'level-complete', bonus: 1000 * this.level });
  }

  gameOver() {
    this.state = STATES.GAME_OVER;
    this.events.push({ type: 'game-over' });
  }

  launch() {
    if (this.state === STATES.READY) {
      this.state = STATES.PLAYING;
      this.balls.forEach(b => {
        if (b.stuck) {
          b.stuck = false;
          b.stuckToPaddle = false;
        }
      });
    }
  }

  pause() {
    if (this.state === STATES.PLAYING) {
      this.state = STATES.PAUSED;
    } else if (this.state === STATES.PAUSED) {
      this.state = STATES.PLAYING;
    }
  }

  movePaddle(x) {
    const newX = Math.max(0, Math.min(x, CANVAS_WIDTH - this.paddle.width));
    this.paddle.vx = (newX - this.paddle.x) / PHYSICS_STEP;
    this.paddle.x = newX;
  }

  clone() {
    const gs = new GameState(this.level, this.baseSpeed, this.speedCap, [], this.constants);
    gs.score = this.score;
    gs.lives = this.lives;
    gs.combo = this.combo;
    gs.nextExtraLife = this.nextExtraLife;
    gs.paddle = this.paddle.clone();
    gs.balls = this.balls.map(b => b.clone());
    gs.drops = this.drops.map(d => d.clone());
    gs.power = this.power;
    gs.powerSeconds = this.powerSeconds;
    gs.bricks = this.bricks.map(b => b.clone());
    gs.state = this.state;
    gs.simulationTime = this.simulationTime;
    gs.accumulator = this.accumulator;
    gs.events = [...this.events];
    gs.lastBrickHitId = this.lastBrickHitId;
    gs.assistPaddleActive = this.assistPaddleActive;
    return gs;
  }
}

module.exports = {
  GameState,
  STATES,
  CANVAS_WIDTH,
  CANVAS_HEIGHT,
  BRICK_WIDTH,
  BRICK_HEIGHT,
  BRICK_PADDING,
  PADDLE_HEIGHT,
  BALL_RADIUS
};

const express = require('express');
const path = require('path');
const crypto = require('crypto');
const { getDb, initializeDatabase, seedDatabase } = require('./src/db');
const { signIn, verifyToken, signOut, getRunRevision } = require('./src/auth');
const { GameState, STATES } = require('./src/gamestate');

const app = express();
const PORT = 3000;

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

// Middleware to verify token
async function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const user = await verifyToken(token);
    if (!user) {
      return res.status(401).json({ error: 'Invalid token' });
    }
    req.user = user;
    req.token = token;
    next();
  } catch (err) {
    console.error('Token verification error:', err);
    res.status(401).json({ error: 'Token verification failed' });
  }
}

// Helper to get constants
function getConstants() {
  return new Promise((resolve, reject) => {
    const db = getDb();
    db.all("SELECT key, value FROM constants", (err, rows) => {
      db.close();
      if (err) {
        reject(err);
      } else {
        const constants = {};
        rows.forEach(row => {
          const val = isNaN(row.value) ? row.value : parseInt(row.value);
          constants[row.key] = val;
        });
        resolve(constants);
      }
    });
  });
}

// Helper to get level data
function getLevelData(level) {
  return new Promise((resolve, reject) => {
    const db = getDb();
    db.get("SELECT * FROM levels WHERE level = ?", [level], (err, levelRow) => {
      if (err) {
        db.close();
        reject(err);
        return;
      }

      db.all("SELECT * FROM bricks WHERE level = ? ORDER BY row, column", [level], (err, brickRows) => {
        db.close();
        if (err) {
          reject(err);
        } else {
          resolve({
            level: levelRow,
            bricks: brickRows
          });
        }
      });
    });
  });
}

// Helper to create brick objects for game state
function createBrickObjects(brickRows) {
  const BRICK_WIDTH = 80;
  const BRICK_HEIGHT = 20;
  const BRICK_PADDING = 5;
  const START_X = 10;
  const START_Y = 50;

  return brickRows.map(brick => ({
    x: START_X + (brick.column - 1) * (BRICK_WIDTH + BRICK_PADDING),
    y: START_Y + (brick.row - 1) * (BRICK_HEIGHT + BRICK_PADDING),
    width: BRICK_WIDTH,
    height: BRICK_HEIGHT,
    type: brick.type,
    drop: brick.drop
  }));
}

// Sign in endpoint
app.post('/api/signin', async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }

  try {
    const result = await signIn(email, password);
    if (!result) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    res.json({
      token: result.token,
      user: result.user
    });
  } catch (err) {
    console.error('Sign in error:', err);
    res.status(500).json({ error: 'Sign in failed' });
  }
});

// Sign out endpoint
app.post('/api/signout', authenticateToken, async (req, res) => {
  try {
    await signOut(req.token);
    res.json({ success: true });
  } catch (err) {
    console.error('Sign out error:', err);
    res.status(500).json({ error: 'Sign out failed' });
  }
});

// Get user profile
app.get('/api/profile', authenticateToken, (req, res) => {
