function startGameLoop() {
  lastFrameTime = performance.now();
  animate();
}

function animate(currentTime = performance.now()) {
  const deltaTime = Math.min((currentTime - lastFrameTime) / 1000, 0.016);
  lastFrameTime = currentTime;

  update(deltaTime);
  render();

  animationId = requestAnimationFrame(animate);
}

function update(deltaTime) {
  if (!gameState) return;

  // Update game state
  let accumulator = deltaTime;

  while (accumulator >= PHYSICS_STEP && gameState.state !== 'paused' && gameState.state !== 'ready') {
    simulationStep();
    accumulator -= PHYSICS_STEP;
  }

  updateHUD();

  // Auto-save periodically
  if (Date.now() - lastSaveTime > SAVE_INTERVAL && gameState.state === 'playing') {
    saveRun();
    lastSaveTime = Date.now();
  }
}

function simulationStep() {
  if (!gameState || gameState.state === 'paused' || gameState.state === 'ready') return;

  // Update power-up timer
  if (gameState.power) {
    gameState.power_seconds -= PHYSICS_STEP;
    if (gameState.power_seconds <= 0) {
      endPowerUp();
    }
  }

  // Update drops
  updateDrops();

  // Update balls
  updateBalls();

  // Check for level completion
  const breakableBricks = gameState.bricks.filter(b => b.type !== 'solid' && b.health > 0);
  if (breakableBricks.length === 0) {
    completeLevel();
  }

  // Check for game over
  if (gameState.balls.length === 0 && gameState.lives === 0) {
    gameOver();
  }
}

function updateBalls() {
  const ballsCopy = [...gameState.balls];

  for (let i = 0; i < ballsCopy.length; i++) {
    const ball = ballsCopy[i];

    if (ball.stuck) {
      ball.x = paddleX + gameState.paddle_width / 2;
      ball.y = CANVAS_HEIGHT - 40 - BALL_RADIUS;
      continue;
    }

    const newX = ball.x + ball.vx * PHYSICS_STEP;
    const newY = ball.y + ball.vy * PHYSICS_STEP;

    // Check brick collisions
    let hitBrick = null;
    for (let j = 0; j < gameState.bricks.length; j++) {
      const brick = gameState.bricks[j];
      if (brick.health > 0 && checkCircleRectCollision(ball.x, ball.y, BALL_RADIUS, brick.x, brick.y, brick.width, brick.height)) {
        hitBrick = j;
        break;
      }
    }

    if (hitBrick !== null) {
      const brick = gameState.bricks[hitBrick];
      const collision = getCollisionNormal(ball.x, ball.y, BALL_RADIUS, brick.x, brick.y, brick.width, brick.height);

      ball.x = collision.point.x;
      ball.y = collision.point.y;

      const speed = Math.sqrt(ball.vx ** 2 + ball.vy ** 2);
      const reflected = reflectVelocity(ball.vx, ball.vy, collision.normal.x, collision.normal.y);
      ball.vx = reflected.x;
      ball.vy = reflected.y;

      // Ensure minimum velocity
      const newSpeed = Math.sqrt(ball.vx ** 2 + ball.vy ** 2);
      if (newSpeed < MIN_VELOCITY && newSpeed > 0) {
        const factor = MIN_VELOCITY / newSpeed;
        ball.vx *= factor;
        ball.vy *= factor;
      }

      // Damage brick
      if (brick.type !== 'solid') {
        if (brick.type === 'normal') {
          gameState.score += 100 * gameState.combo;
          brick.health = 0;
        } else if (brick.type === 'strong') {
          if (!brick.damaged) {
            gameState.score += 75 * gameState.combo;
            brick.damaged = true;
          } else {
            gameState.score += 250 * gameState.combo;
            brick.health = 0;
          }
        }

        gameState.combo = Math.min(gameState.combo + 1, 5);

        // Check for extra life
        if (gameState.score >= gameState.next_extra_life) {
          gameState.lives++;
          gameState.next_extra_life += constants.extra_life_step;
        }
      }
    } else {
      // Check paddle collision
      if (checkCircleRectCollision(ball.x, ball.y, BALL_RADIUS, paddleX, CANVAS_HEIGHT - 40, gameState.paddle_width, PADDLE_HEIGHT)) {
        const collision = getCollisionNormal(ball.x, ball.y, BALL_RADIUS, paddleX, CANVAS_HEIGHT - 40, gameState.paddle_width, PADDLE_HEIGHT);

        ball.x = collision.point.x;
        ball.y = collision.point.y;

        // Steering
        const paddleCenter = paddleX + gameState.paddle_width / 2;
        const hitOffset = (ball.x - paddleCenter) / (gameState.paddle_width / 2);
        const steerAngle = Math.max(-Math.PI / 6, Math.min(Math.PI / 6, hitOffset * Math.PI / 6));

        const speed = Math.sqrt(ball.vx ** 2 + ball.vy ** 2);
        ball.vx = Math.sin(steerAngle) * speed;
        ball.vy = -Math.cos(steerAngle) * speed;

        gameState.combo = 1;

        if (ball.stuck) {
          ball.stuck = false;
        }
      } else {
        ball.x = newX;
        ball.y = newY;
      }
    }

    // Check if out of bounds
    if (ball.y > CANVAS_HEIGHT) {
      gameState.balls = gameState.balls.filter(b => b.id !== ball.id);

      if (gameState.balls.length === 0) {
        loseLife();
      }
    }
  }
}

function updateDrops() {
  for (let i = gameState.drops.length - 1; i >= 0; i--) {
    const drop = gameState.drops[i];
    drop.y += drop.vy * PHYSICS_STEP;

    // Check paddle collision
    if (drop.y + 8 > CANVAS_HEIGHT - 40 &&
        drop.y - 8 < CANVAS_HEIGHT - 40 + PADDLE_HEIGHT &&
        drop.x + 8 > paddleX &&
        drop.x - 8 < paddleX + gameState.paddle_width) {

      collectPowerUp(drop.type);
      gameState.drops.splice(i, 1);
    } else if (drop.y > CANVAS_HEIGHT) {
      gameState.drops.splice(i, 1);
    }
  }
}

function collectPowerUp(type) {
  if (gameState.power === type) {
    gameState.power_seconds = constants.powerup_duration_seconds;
  } else {
    if (gameState.power) {
      endPowerUp();
    }

    gameState.power = type;
    gameState.power_seconds = constants.powerup_duration_seconds;

    if (type === 'wide') {
      gameState.paddle_width = 118 * 1.5;
    } else if (type === 'slow') {
      const speed = Math.sqrt(gameState.balls[0].vx ** 2 + gameState.balls[0].vy ** 2);
      const newSpeed = speed * 0.7;
      const factor = newSpeed / speed;
      gameState.balls.forEach(b => {
        b.vx *= factor;
        b.vy *= factor;
      });
    } else if (type === 'multiball') {
      if (gameState.balls.length === 1) {
        const primary = gameState.balls[0];
        gameState.balls.push({
          id: 'secondary',
          x: primary.x,
          y: primary.y,
          vx: primary.vx,
          vy: primary.vy,
          stuck: false
        });
      }
    } else if (type === 'sticky') {
      if (gameState.balls.length > 0) {
        gameState.balls[0].stuck = true;
      }
    }
  }
}

function endPowerUp() {
  if (gameState.power === 'wide') {
    gameState.paddle_width = 118;
  } else if (gameState.power === 'slow') {
    gameState.balls.forEach(b => {
      const speed = Math.sqrt(b.vx ** 2 + b.vy ** 2);
      if (speed > 0) {
        const factor = Math.min(constants.speed_cap, speed) / speed;
        b.vx *= factor;
        b.vy *= factor;
      }
    });
  } else if (gameState.power === 'multiball') {
    gameState.balls = gameState.balls.filter(b => b.id === 'primary');
  } else if (gameState.power === 'sticky') {
    if (gameState.balls.length > 0 && gameState.balls[0].stuck) {
      gameState.balls[0].stuck = false;
    }
  }

  gameState.power = null;
  gameState.power_seconds = 0;
}

function loseLife() {
  gameState.lives--;
  gameState.drops = [];
  endPowerUp();

  if (gameState.lives > 0) {
    gameState.state = 'life-lost';
  } else {
    gameOver();
  }
}

function completeLevel() {
  gameState.score += 1000 * gameState.level;
  gameState.state = 'level-complete';
}

function gameOver() {
  gameState.state = 'game-over';
}

function render() {
  if (!gameState) return;

  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

  // Draw bricks
  gameState.bricks.forEach(brick => {
    if (brick.health > 0) {
      if (brick.type === 'solid') {
        ctx.fillStyle = '#333';
      } else if (brick.type === 'strong') {
        ctx.fillStyle = brick.damaged ? '#ff6b6b' : '#ff8c42';
      } else {
        ctx.fillStyle = '#2ecc71';
      }

      ctx.fillRect(brick.x, brick.y, brick.width, brick.height);
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 1;
      ctx.strokeRect(brick.x, brick.y, brick.width, brick.height);
    }
  });

  // Draw drops
  gameState.drops.forEach(drop => {
    const colors = {
      'wide': '#3498db',
      'slow': '#f39c12',
      'multiball': '#e74c3c',
      'sticky': '#9b59b6'
    };
    ctx.fillStyle = colors[drop.type] || '#fff';
    ctx.beginPath();
    ctx.arc(drop.x, drop.y, 8, 0, Math.PI * 2);
    ctx.fill();
  });

  // Draw paddle
  ctx.fillStyle = '#f39c12';
  ctx.fillRect(paddleX, CANVAS_HEIGHT - 40, gameState.paddle_width, PADDLE_HEIGHT);
  ctx.strokeStyle = '#fff';
  ctx.lineWidth = 2;
  ctx.strokeRect(paddleX, CANVAS_HEIGHT - 40, gameState.paddle_width, PADDLE_HEIGHT);

  // Draw balls
  gameState.balls.forEach(ball => {
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, BALL_RADIUS, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#f39c12';
    ctx.lineWidth = 2;
    ctx.stroke();
  });

  // Draw state overlay
  if (gameState.state === 'ready') {
    drawOverlay('READY', 'Press SPACE to launch');
  } else if (gameState.state === 'paused') {
    drawOverlay('PAUSED', 'Press P to resume');
  } else if (gameState.state === 'life-lost') {
    drawOverlay('LIFE LOST', 'Press SPACE to continue');
  } else if (gameState.state === 'level-complete') {
    drawOverlay('LEVEL COMPLETE', 'Press SPACE to continue');
  } else if (gameState.state === 'game-over') {
    drawOverlay('GAME OVER', 'Press R to restart');
  } else if (gameState.state === 'completed') {
    drawOverlay('COMPLETED!', 'You beat the game!');
  }
}

function drawOverlay(title, subtitle) {
  ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
  ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

  ctx.fillStyle = '#f39c12';
  ctx.font = 'bold 48px Arial';
  ctx.textAlign = 'center';
  ctx.fillText(title, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2 - 30);

  ctx.fillStyle = '#fff';
  ctx.font = '24px Arial';
  ctx.fillText(subtitle, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2 + 30);
}

function updateHUD() {
  if (!gameState) return;

  document.getElementById('scoreDisplay').textContent = gameState.score;
  document.getElementById('livesDisplay').textContent = gameState.lives;
  document.getElementById('levelDisplay').textContent = gameState.level;
