    if (gameState.level === 10) {
      finishRun('completed');
    } else {
      startNewRun(gameState.level + 1);
    }
  } else if (gameState.state === 'game-over') {
    finishRun('game-over');
  }
}

function togglePause() {
  if (!gameState) return;

  if (gameState.state === 'playing') {
    gameState.state = 'paused';
  } else if (gameState.state === 'paused') {
    gameState.state = 'playing';
  }
}

function restartGame() {
  if (!gameState) return;
  showLevelSelect();
}

function movePaddle(x) {
  paddleX = Math.max(0, Math.min(x, CANVAS_WIDTH - gameState.paddle_width));
}

function toggleAssist() {
  assistPaddleActive = document.getElementById('assistCheckbox').checked;
}

function showSignIn() {
  document.getElementById('signInSection').style.display = 'block';
  document.getElementById('gameSection').style.display = 'none';
}

function signOut() {
  fetch('/api/signout', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${token}` }
  }).then(() => {
    token = null;
    localStorage.removeItem('brickfall_token');
    currentUser = null;
    gameState = null;
